local a=base
local selector={{false,true,true,false},{true,true,false,true},{true,false,true,true}}
local values=np.array(2.0,"float64")
local ok,result=pcall(function() return np.copyto(a,values,"equiv",selector) end)
assert(ok==false,"bool/plain/array(2.)/equiv/[[False, True, True, False], [True, True, False, True], [True, False, True, True]]: acceptance")
if ok then assert(result==nil,"bool/plain/array(2.)/equiv/[[False, True, True, False], [True, True, False, True], [True, False, True, True]]: return") end
eq(base:tolist(),{{false,true,false,true},{false,true,false,true},{false,true,false,true}},"bool/plain/array(2.)/equiv/[[False, True, True, False], [True, True, False, True], [True, False, True, True]]")
eq(a.shape,{3,4},"bool/plain/array(2.)/equiv/[[False, True, True, False], [True, True, False, True], [True, False, True, True]]: shape")
eq(a.strides,{4,1},"bool/plain/array(2.)/equiv/[[False, True, True, False], [True, True, False, True], [True, False, True, True]]: strides")
cases=cases+1
end
