local base=np.array({{false,true,false,true},{false,true,false,true},{false,true,false,true}},"bool")
local a=np.transpose(base)
local selector={{false,true,true},{false,true,true},{false,true,true},{false,true,true}}
local values=np.array({0,1,2},"int16")
local ok,result=pcall(function() return np.copyto(a,values,"no",selector) end)
assert(ok==false,"bool/transpose/array([0, 1, 2], dtype=int16)/no/[[False, True, True], [False, True, True], [False, True, True], [False, True, True]]: acceptance")
if ok then assert(result==nil,"bool/transpose/array([0, 1, 2], dtype=int16)/no/[[False, True, True], [False, True, True], [False, True, True], [False, True, True]]: return") end
eq(base:tolist(),{{false,true,false,true},{false,true,false,true},{false,true,false,true}},"bool/transpose/array([0, 1, 2], dtype=int16)/no/[[False, True, True], [False, True, True], [False, True, True], [False, True, True]]")
eq(a.shape,{4,3},"bool/transpose/array([0, 1, 2], dtype=int16)/no/[[False, True, True], [False, True, True], [False, True, True], [False, True, True]]: shape")
eq(a.strides,{1,4},"bool/transpose/array([0, 1, 2], dtype=int16)/no/[[False, True, True], [False, True, True], [False, True, True], [False, True, True]]: strides")
cases=cases+1
end
