local base=np.array({{false,true,false,true},{false,true,false,true},{false,true,false,true}},"bool")
local a=np.transpose(base)
local selector=true
local values={2,2,2}
local ok,result=pcall(function() return np.copyto(a,values,"unsafe",selector) end)
assert(ok==true,"bool/transpose/[2, 2, 2]/unsafe/True: acceptance")
if ok then assert(result==nil,"bool/transpose/[2, 2, 2]/unsafe/True: return") end
eq(base:tolist(),{{true,true,true,true},{true,true,true,true},{true,true,true,true}},"bool/transpose/[2, 2, 2]/unsafe/True")
eq(a.shape,{4,3},"bool/transpose/[2, 2, 2]/unsafe/True: shape")
eq(a.strides,{1,4},"bool/transpose/[2, 2, 2]/unsafe/True: strides")
cases=cases+1
end
